fn to_lowercase(s: &Vec<char>) -> Vec<char> {
    s.iter()
        .map(|&c| {
            if ('A'..='Z').contains(&c) {
                // Convert uppercase ASCII to lowercase by adding 32
                // This is safe since it's ASCII letters.
                ((c as u8) + 32) as char
            } else {
                c
            }
        })
        .collect()
}